void Loader_menuDef_t::LoadPtr_menuDef_t(const bool atStreamStart)
{
    assert(varmenuDef_tPtr != nullptr);
    
    assert(!atStreamStart);
    
    m_stream.PushBlock(XFILE_BLOCK_TEMP);
    
    if (*varmenuDef_tPtr != nullptr)
    {
        const auto zonePtrType = GetZonePointerType(*varmenuDef_tPtr);
        if (zonePtrType == ZonePointerType::FOLLOWING || zonePtrType == ZonePointerType::INSERT)
        {
            *varmenuDef_tPtr = m_stream.AllocOutOfBlock<menuDef_t>(4);
            
            uintptr_t toInsertLookupEntry = 0;
            if (zonePtrType == ZonePointerType::INSERT)
                toInsertLookupEntry = m_stream.InsertPointerAliasLookup();
            
            varmenuDef_t = *varmenuDef_tPtr;
            Load_menuDef_t(true);
            
            LoadAsset_menuDef_t(varmenuDef_tPtr);
            
            if (zonePtrType == ZonePointerType::INSERT)
                m_stream.SetInsertedPointerAliasLookup(toInsertLookupEntry, *varmenuDef_tPtr);
        }
        else
        {
            *varmenuDef_tPtr = m_stream.ConvertOffsetToAliasLookup(*varmenuDef_tPtr);
        }
    }
    
    m_stream.PopBlock();
}

void Loader_menuDef_t::LoadAsset_menuDef_t(menuDef_t** pAsset)
{
    assert(pAsset != nullptr);
    
    AssetInfoCollector assetInfo(m_zone);
    AssetMarker<AssetMenu> marker(assetInfo);
    marker.Mark(*pAsset);
    
    auto* reallocatedAsset = m_zone.Memory().Alloc<menuDef_t>();
    std::memcpy(reallocatedAsset, *pAsset, sizeof(menuDef_t));
    
    m_asset_info = reinterpret_cast<XAssetInfo<menuDef_t>*>(LinkAsset(AssetName<AssetMenu>(**pAsset), reallocatedAsset, assetInfo.GetDependencies(), assetInfo.GetUsedScriptStrings(), assetInfo.GetIndirectAssetReferences()));
    *pAsset = m_asset_info->Asset();
}
